@@ -302,16 +302,26 @@ public class FastDateParser implements DateParser, Serializable {
      */
     private static StringBuilder escapeRegex(StringBuilder regex, String value, boolean unquote) {
         boolean wasWhite= false;
+        int whiteCount= 0;
         for(int i= 0; i<value.length(); ++i) {
             char c= value.charAt(i);
             if(Character.isWhitespace(c)) {
                 if(!wasWhite) {
                     wasWhite= true;
-                    regex.append("\\s*+");
+                    whiteCount= 1;
+                } else {
+                    whiteCount++;
                 }
                 continue;
             }
-            wasWhite= false;
+            if(wasWhite) {
+                wasWhite= false;
+                if(whiteCount == 1) {
+                    regex.append("\\s");
+                } else {
+                    regex.append("\\s{").append(whiteCount).append("}");
+                }
+            }
             switch(c) {
             case '\'':
                 if(unquote) {
@@ -339,6 +349,13 @@ public class FastDateParser implements DateParser, Serializable {
             }
             regex.append(c);
         }
+        if(wasWhite) {
+            if(whiteCount == 1) {
+                regex.append("\\s");
+            } else {
+                regex.append("\\s{").append(whiteCount).append("}");
+            }
+        }
         return regex;
     }
